export function generateDockerignore(): string {
  return [
    "# Auto-generated by biodome",
    "# These files are not needed inside the Docker build context.",
    "",
    ".git",
    ".gitignore",
    ".biodome/node_modules/",
    ".biodome-build/*",
    "!.biodome-build/supervisord.conf",
    "!.biodome-build/targets",
    "!.biodome-build/targets/**",
    ".data",
    "node_modules",
    ".venv",
    "venv",
    "__pycache__",
    "*.pyc",
    "*.pyo",
    "target",
    "*.log",
    ".env",
    ".env.*",
    "*.env",
    "Dockerfile",
    ".dockerignore",
    "docker-compose.yaml",
    "docker-compose.yml",
    "",
  ].join("\n");
}
